mapper.insert:
INSERT INTO problem_tag_assignment ( problem_id, tag_id, ordinal ) SELECT p.id, pt.id, assignments.ordinal FROM ( VALUES
(#{row.problemSlug}, #{row.tagValue}, #{row.ordinal})
) AS assignments(problem_slug, tag_value, ordinal) JOIN problem p ON p.slug = assignments.problem_slug JOIN problem_tag pt ON pt.value = assignments.tag_value ORDER BY assignments.ordinal ASC

mapper.select:
SELECT value FROM problem_tag WHERE active = FALSE AND value IN
#{value}
ORDER BY value ASC
